def img(name,alt='',cls='',lazy=True): return f'<img class="{cls}" src="/assets/{name}" alt="{E(alt or "Construction concept image")}"'+(' loading="lazy"' if lazy else '')+'>'
def brand():return '''<a class="brand" href="/" aria-label="Strategic Construction Group home"><svg viewBox="0 0 92 74" aria-hidden="true"><path d="M8 61V30l13-7v34M24 57V12L42 2v55M45 57V2l14 8v47M62 57V21l10 6v30" fill="none" stroke="currentColor" stroke-width="5"/><path d="M27 57V13L42 4v53M63 24l8 5v28" fill="#e9a900"/><path d="M2 68c28-10 57-10 87 0" fill="none" stroke="#e4a500" stroke-width="3"/></svg><span><strong>STRATEGIC</strong><small>CONSTRUCTION GROUP</small></span></a>'''
def header(path):
 links=''.join(f'<a href="{url}"'+(' class="active" aria-current="page"' if (path==url or url!="/" and path.startswith(url)) else '')+f'>{name}</a>'+('''<div class="dropdown"><button class="drop-toggle" aria-expanded="false" aria-label="Open services menu">⌄</button><div class="drop-menu">'''+''.join(f'<a href="/services/{s[0]}/">{s[1]}</a>' for s in services)+'</div></div>' if name=='Services' else '') for name,url in nav)
 return f'''<div class="contactbar"><div class="top-inner"><span>● &nbsp; Cape Town, South Africa <b> | </b> Residential &nbsp; / &nbsp; Commercial &nbsp; / &nbsp; Industrial</span><span class="top-note">BUILDING WITH PURPOSE</span></div></div><header class="header"><div class="nav-inner">{brand()}<button class="menu-toggle" aria-label="Open navigation" aria-expanded="false" aria-controls="navigation"><span></span><span></span><span></span></button><nav id="navigation" aria-label="Main navigation">{links}<a class="nav-quote" href="/request-a-quote/">Request a Quote <span>→</span></a></nav></div></header>'''
def footer():return f'''<footer><div class="wrap footer-grid"><div>{brand()}<p>Thoughtful construction, professional coordination and a commitment to quality across Cape Town and the Western Cape.</p><p>⌖ &nbsp; Cape Town, South Africa</p></div><div><h3>Quick links</h3>{''.join(f'<a href="{u}">{n}</a>' for n,u in nav)}</div><div><h3>Our services</h3>{''.join(f'<a href="/services/{s[0]}/">{s[1]}</a>' for s in services[:6])}</div><div><h3>Contact</h3><p>Cape Town, South Africa</p><p>Residential, commercial and industrial construction.</p><p>Website imagery depicts construction concepts, not company project photographs.</p><a class="footer-cta" href="/request-a-quote/">Start a project →</a></div></div><div class="wrap footer-bottom"><span>© {datetime.date.today().year} Strategic Construction Group</span><span><a href="/privacy-policy/">Privacy Policy</a> &nbsp; / &nbsp; <a href="/terms-and-conditions/">Terms &amp; Conditions</a></span></div></footer><a class="backtop" href="#top" aria-label="Back to top">↑</a>'''
def cta(title="Let's Build Something Exceptional.",text='Have a construction project in mind? Speak to our team about bringing your vision to life.',button='Request a Quote'):return f'''<section class="cta"><div class="wrap cta-inner"><div><p class="kicker gold">YOUR VISION. OUR FOCUS.</p><h2>{title}</h2><p>{text}</p></div><a class="btn gold-btn" href="/request-a-quote/">{button} <span>→</span></a></div></section>'''
def banner(title,text,image='cape-town.jpg',tag='STRATEGIC CONSTRUCTION GROUP'):return f'''<section class="page-hero" style="--bg:url('/assets/{image}')"><div class="wrap"><p class="kicker">{tag}</p><h1>{title}</h1><p>{text}</p></div></section>'''
def intro(kicker,title,text=''):return f'<div class="section-head"><div><p class="kicker gold">{kicker}</p><h2>{title}</h2></div><p>{text}</p></div>'
def cards(items=services):return '<div class="service-grid">'+''.join(f'''<a class="service-card" href="/services/{s[0]}/">{img(s[5],s[1]+' concept image')}<div><span class="service-num">{i+1:02d} / SERVICE</span><h3>{s[1]}</h3><p>{s[2]}</p><span class="text-link">Explore service ↗</span></div></a>''' for i,s in enumerate(items))+'</div>'
def project_cards(items=projects):return '<div class="project-grid">'+''.join(f'''<article class="project-card" data-category="{E(p['category'])}"><a href="/projects/{p['slug']}/">{img(p['cover'],p['title']+' project photograph')}<span class="image-badge">PROJECT</span></a><div class="project-body"><p class="project-meta">{E(p['category']).upper()} &nbsp; / &nbsp; {E(p['location']).upper()}</p><h3>{E(p['title'])}</h3><p>{E(p['description'])}</p><a class="text-link" href="/projects/{p['slug']}/">View project →</a></div></article>''' for p in items)+'</div>'
def disclaimer():return ''
def render(path,title,desc,body):
 canon=base+path
 content=f'''<!doctype html><html lang="en-ZA"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{E(title)} | Strategic Construction Group</title><meta name="description" content="{E(desc)}"><link rel="canonical" href="{canon}"><meta property="og:title" content="{E(title)} | Strategic Construction Group"><meta property="og:description" content="{E(desc)}"><meta property="og:type" content="website"><meta property="og:url" content="{canon}"><meta property="og:image" content="{base}/assets/cape-town.jpg"><meta name="theme-color" content="#061f3d"><link rel="stylesheet" href="/styles.css"><script type="application/ld+json">{json.dumps({'@context':'https://schema.org','@type':'ConstructionBusiness','name':'Strategic Construction Group','url':base,'address':{'@type':'PostalAddress','addressLocality':'Cape Town','addressRegion':'Western Cape','addressCountry':'ZA'}})}</script><script src="/app.js" defer></script></head><body id="top">{header(path)}<main>{body}</main>{footer()}<dialog id="lightbox" aria-label="Project image viewer"><button class="light-close" aria-label="Close gallery">×</button><button class="light-prev" aria-label="Previous image">‹</button><figure><img alt=""><figcaption></figcaption></figure><button class="light-next" aria-label="Next image">›</button></dialog></body></html>'''
 out=ROOT/('index.html' if path=='/' else path.strip('/')+'/index.html');out.parent.mkdir(parents=True,exist_ok=True);out.write_text(content)
 return path
