def select(name,options,required=True):return f'<select name="{name}"'+(' required' if required else '')+'><option value="">Please select</option>'+''.join(f'<option>{E(x)}</option>' for x in options)+'</select>'
quote=banner('Tell Us About Your Project.','Tell us about the scope, location and timing of your construction project.','during.jpg','REQUEST A QUOTE')+f'''<section class="section wrap quote-layout"><aside><p class="kicker gold">LET’S GET STARTED</p><h2>Every great build starts with a conversation.</h2><p>A clear brief helps establish the scope of work and the information needed for a quotation. Include the site location, the type of project and any relevant plans or requirements.</p><div class="notice"><b>Please note</b><p>This form currently downloads your completed brief; it does not send an enquiry to our team.</p></div></aside><div class="form-panel"><form class="enquiry-form" data-kind="Project quotation enquiry"><fieldset><legend>01 <span>Client information</span></legend><div class="form-grid"><label>Full name *<input name="Full name" required autocomplete="name"></label><label>Email address *<input name="Email" type="email" required autocomplete="email"></label><label>Telephone number *<input name="Telephone" type="tel" required autocomplete="tel"></label><label>Preferred contact method *{select('Preferred contact method',['Email','Telephone'])}</label></div></fieldset><fieldset><legend>02 <span>Project information</span></legend><div class="form-grid"><label>Project name (optional)<input name="Project name"></label><label>Project type *{select('Project type',['Residential Construction','Commercial Construction','Industrial Construction','Renovations and Extensions','Swimming Pool Construction','Civil Works','Project Management','Other'])}</label><label class="wide">Project location *<input name="Project location" required></label><label class="wide">Project description *<textarea name="Project description" rows="5" required></textarea></label></div></fieldset><fieldset><legend>03 <span>Project budget</span></legend><label>Budget range *{select('Budget',['Under R50,000','R50,000 – R100,000','R100,000 – R250,000','R250,000 – R500,000','R500,000 – R1 million','Above R1 million','Not yet determined'])}</label></fieldset><fieldset><legend>04 <span>Project timeline</span></legend><label>When are you planning to start? *{select('Timeline',['Immediately','Within 1–3 months','Within 3–6 months','More than 6 months','Still planning'])}</label></fieldset><fieldset><legend>05 <span>Additional information</span></legend><label>Additional project requirements<textarea name="Additional requirements" rows="4"></textarea></label></fieldset><button class="btn gold-btn" type="submit">Prepare project enquiry →</button><p class="form-feedback" role="status"></p></form></div></section>'''
paths.append(render('/request-a-quote/','Request a Construction Quote','Prepare your construction project enquiry for Strategic Construction Group in Cape Town.',quote))
for slug,title,txt in [('privacy-policy','Privacy Policy','This policy is being reviewed before publication. The business must identify the information it collects, the purpose and lawful basis for processing, retention periods, service providers, security practices, data subject rights and contact details. The contact and quote forms on this site do not currently transmit information.'),('terms-and-conditions','Terms and Conditions','This policy is being reviewed before publication. The business must define the terms for use of this website, intellectual property, limitations of liability, external links, applicable law and contact details. Website content is informational and does not constitute a construction quotation or agreement.')]:
 body=banner(title,'Legal information subject to review.','cape-town.jpg','LEGAL')+f'<section class="section wrap narrow"><p class="notice"><b>Important:</b> This policy is under review and is not yet final.</p><h2>{title}</h2><p>{txt}</p></section>'
 paths.append(render('/'+slug+'/',title,'Draft '+title+' for review.',body))
